from django.apps import apps

def get_invoice_model():
    return apps.get_model("billing", "Invoice")


def create_invoice(data):
    Invoice = get_invoice_model()
    return Invoice.objects.create(**data)

from django.http import StreamingHttpResponse

def stream_rows(rows):
    yield "id,name\n"
    for r in rows.iterator(chunk_size=1000):
        yield f"{r.id},{r.name}\n"

def export_users(request):
    return StreamingHttpResponse(stream_rows(User.objects.all()), content_type="text/csv")

